   723  otError NcpBase::SendQueuedResponses(void)
   724  {
   725      otError error = OT_ERROR_NONE;
   726
   727      while (mResponseQueueHead != mResponseQueueTail)
   728      {
   729          ResponseEntry &entry = mResponseQueue[mResponseQueueHead];
   730
   731          if (entry.mIsInUse)
   732          {
   733              uint8_t header = SPINEL_HEADER_FLAG | SPINEL_HEADER_IID_0;
   734
   735              header |= static_cast<uint8_t>(entry.mTid << SPINEL_HEADER_TID_SHIFT);
   736
   737              if (entry.mType == kResponseTypeLastStatus)
   738              {
   739                  spinel_status_t status = static_cast<spinel_status_t>(entry.mPropKeyOrStatus);
   740
   741                  SuccessOrExit(error = WriteLastStatusFrame(header, status));
   742              }
   743              else
   744              {
   745                  spinel_prop_key_t propKey       = static_cast<spinel_prop_key_t>(entry.mPropKeyOrStatus);
   746                  bool              isGetResponse = (entry.mType == kResponseTypeGet);
   747
   748                  SuccessOrExit(error = WritePropertyValueIsFrame(header, propKey, isGetResponse));
   749              }
   750          }
   751
   752          // Remove the response entry.
   753
   754          entry.mIsInUse = false;
   755
   756          mResponseQueueHead++;
   757
   758          if (mResponseQueueHead == kResponseQueueSize)
   759          {
   760              // Only when `head` wraps, the `tail` will be wrapped as well.
   761              //
   762              // This ensures that `tail` is always bigger than `head` and
   763              // `(tail - head)` to correctly give the number of items in
   764              // the queue.
   765
   766              mResponseQueueHead = 0;
   767              mResponseQueueTail = GetWrappedResponseQueueIndex(mResponseQueueTail);
   768          }
   769      }
   770
   771  exit:
   772      return error;
   773  }
