   785  void NcpBase::UpdateChangedProps(void)
   786  {
   787      uint8_t                       numEntries;
   788      spinel_prop_key_t             propKey;
   789      const ChangedPropsSet::Entry *entry;
   790
   791  #if OPENTHREAD_MTD || OPENTHREAD_FTD
   792      ProcessThreadChangedFlags();
   793  #endif
   794
   795      VerifyOrExit(!mChangedPropsSet.IsEmpty());
   796
   797      entry = mChangedPropsSet.GetSupportedEntries(numEntries);
   798
   799      for (uint8_t index = 0; index < numEntries; index++, entry++)
   800      {
   801          if (!mChangedPropsSet.IsEntryChanged(index))
   802          {
   803              continue;
   804          }
   805
   806          propKey = entry->mPropKey;
   807
   808          if (propKey == SPINEL_PROP_LAST_STATUS)
   809          {
   810              spinel_status_t status = entry->mStatus;
   811
   812              if (status == SPINEL_STATUS_RESET_UNKNOWN)
   813              {
   814                  status = ResetReasonToSpinelStatus(otPlatGetResetReason(mInstance));
   815              }
   816
   817              SuccessOrExit(WriteLastStatusFrame(SPINEL_HEADER_FLAG | SPINEL_HEADER_IID_0, status));
   818          }
   819          else if (mDidInitialUpdates)
   820          {
   821              SuccessOrExit(WritePropertyValueIsFrame(SPINEL_HEADER_FLAG | SPINEL_HEADER_IID_0, propKey));
   822          }
   823
   824          mChangedPropsSet.RemoveEntry(index);
   825          VerifyOrExit(!mChangedPropsSet.IsEmpty());
   826      }
   827
   828  exit:
   829      mDidInitialUpdates = true;
   830  }
